/// <summary>
/// PricingAttribute of table <c>SalesLine</c> field TaxGroup.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesLine, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeSalesLineTaxGroup extends UPSPricingAttributeSalesLine implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesLine, TaxGroup);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::String);
    SalesLine   salesLine;

    while select salesLine
        group by TaxGroup
    {
        if (! ret.in(salesLine.TaxGroup))
        {
            ret.add(salesLine.TaxGroup);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesLine, TaxGroup));
    qbr.value(queryValue(_value));
}
